sp_widget.client_script:
function() {
    var c = this;

    // Load data on widget load
    c.server.get({ action: 'refresh' }).then(function(response) {
        c.data.visits = response.data.visits;
    });

    // Optional: auto-refresh every 60 seconds
    setInterval(function() {
        c.server.get({ action: 'refresh' }).then(function(response) {
            c.data.visits = response.data.visits;
        });
    }, 60000);
}

sp_widget.script:
(function() {
    var visits = [];

    var gr = new GlideRecord('x_2137028_validp_0_visit');
    gr.addQuery('sys_created_by', gs.getUserName());
    gr.orderByDesc('sys_created_on');
    gr.setLimit(20);
    gr.query();

    while (gr.next()) {
        // Safely read each reference
        var visitorName = '';
        if (!gr.u_visitor.nil()) {
            visitorName = gr.u_visitor.getDisplayValue();
        }

        var vehiclePlate = '';
        if (!gr.u_vehicle.nil()) {
            vehiclePlate = gr.u_vehicle.u_vehicle_number.toString();
        }

        var slotNumber = '';
        var slotType   = '';
        if (!gr.u_parking_slot.nil()) {
            slotNumber = gr.u_parking_slot.u_slot_number.toString();
            slotType   = gr.u_parking_slot.u_slot_type.toString();
        }

        visits.push({
            sys_id:         gr.getUniqueValue(),
            visitor_name:   visitorName || 'N/A',
            vehicle_plate:  vehiclePlate || 'N/A',
            slot_number:    slotNumber,
            slot_type:      slotType,
            status:         gr.u_status.getDisplayValue() || 'N/A',
            status_raw:     gr.u_status.toString(),
            arrival_time:   gr.u_check_in.getDisplayValue() || 'Not set'
        });
    }

    data.visits = visits;
})();
